      grammar: [
        { id: "en:quantifiers-plural-nouns", ref: "EGP 333", pattern: "all / both / a few + plural noun", name: "quantifiers with plural nouns", note: "a few friends, both hands. Not a few friend." },
        { id: "en:quantifiers-plural-and-uncountable", ref: "EGP 334", pattern: "some / any / no / more / a lot of", name: "quantifiers for both noun types", note: "some milk, some eggs. These words work with plural and uncountable nouns." },
        { id: "en:quantifiers-singular-nouns", ref: "EGP 335", pattern: "each / every / one + singular noun", name: "quantifiers with singular nouns", note: "each student, every day. Not every days." },
        { id: "en:much-negative", ref: "EGP 336", pattern: "not + much + uncountable noun", name: "much in negatives", note: "We don't have much time. Not We have much time (use a lot of)." },
        { id: "en:many-negative", ref: "EGP 337", pattern: "not + many + plural noun", name: "many in negatives", note: "There aren't many shops. Not There aren't many shop." },
        { id: "en:so-many-too-many", ref: "EGP 338", pattern: "so / too many + plural noun", name: "so many and too many", note: "There are too many cars. Not too much cars." },
        { id: "en:quantifier-of-determiner", ref: "EGP 339", pattern: "all / some / most of + the / my + noun", name: "quantifier + of", note: "Some of my friends; all of the cake. Not some of friends." },
      ],
