      grammar: [
        { id: "en:reported-statements", ref: "EGP 1145", pattern: "said / told + (that) + clause", name: "reported statements", note: "Move the tense one step back when you report: She said she was tired. Not She said she is tired for a past report." },
        { id: "en:reported-questions", ref: "EGP 1146", pattern: "asked if / whether + clause", name: "reported yes-no questions", note: "Use if or whether and normal word order: He asked if I was ready. Not He asked was I ready." },
        { id: "en:reported-wh-questions", ref: "EGP 1147", pattern: "asked + wh-word + clause", name: "reported wh- questions", note: "Wh- word then statement order: She asked where I lived. Not where did I live." },
        { id: "en:wonder-reported-thought", ref: "EGP 1148", pattern: "I wondered + wh-word + clause", name: "wonder for reported thought", note: "Wonder + wh- word reports a thought: I wondered what he meant. Not what did he mean." },
        { id: "en:direct-speech-reporting-clause-first", ref: "EGP 1149", pattern: "She said, \"…\"", name: "direct speech with the reporting clause first", note: "Verb before the quote, with a comma: He said, \"I'm tired.\"" },
        { id: "en:direct-speech-reporting-clause-last", ref: "EGP 1150", pattern: "\"…,\" she said", name: "direct speech with the reporting clause last", note: "Quote first, comma inside the marks, then the verb: \"I'm tired,\" he said." },
        { id: "en:reported-commands", ref: "EGP 1151", pattern: "told / asked + sb + to V", name: "reported requests and commands", note: "Told or asked + person + to + verb: She told me to wait. Not She told me wait." },
        { id: "en:reported-future-time-shifts", ref: "EGP 1152", pattern: "said he would … the next day", name: "time shifts in reported future", note: "Time words may change: tomorrow becomes the next day. He said he would come the next day." },
      ],
      topics: ["Repeating a message", "Telling what someone asked you", "Reporting plans"],
      words: ["said", "told", "asked", "wondered", "if", "whether", "that", "tomorrow"],
