      grammar: [
        { id: "en:let-him-her-them-permission-c1", ref: "EGP 197", pattern: "Let him / her / them + V", name: "let him do it for permission", note: "Says the person may act: Let them speak. Learners add to: Let him to go." },
        { id: "en:dont-let-him-her-them-c1", ref: "EGP 198", pattern: "Don't let him / her / them + V", name: "don't let him for refusal", note: "Forbids or warns: Don't let her leave. Learners write Don't let her to leave or use no let." },
        { id: "en:imperative-pointing-formal-c1", ref: "EGP 199", pattern: "See / Note / Refer to + N", name: "imperatives for pointing in texts", note: "Guides the reader: See Table 2. Learners write you should see, which is longer and less formal." },
        { id: "en:imperative-and-conditional-c1", ref: "EGP 200", pattern: "Imperative + and + result", name: "imperative then and for a condition", note: "Condition and result: Push this button and the door opens. Learners add if or will here: If push this button, it will open." },
      ],
      topics: ["giving permission to others", "telling a text where to look", "warning a friend"],
